namespace sv_b681084d8a8c480c8c5735dd6f18f216.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Patel"
    ];

    private static readonly Dictionary<string, List<string>> DoctorSlots = new()
    {
        ["Dr. Smith"] = ["9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM"],
        ["Dr. Johnson"] = ["8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM"],
        ["Dr. Williams"] = ["9:00 AM", "10:30 AM", "11:30 AM", "2:30 PM"],
        ["Dr. Patel"] = ["8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM"],
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableSlotsAsync(string doctor, DateOnly date)
    {
        var slots = DoctorSlots.GetValueOrDefault(doctor, []);
        return Task.FromResult(slots);
    }

    /// <summary>
    /// Validates patient info against server-side rules.
    /// Returns a dictionary of field name → error message for any failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string? timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] =
                "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    public string Email { get; set; } = string.Empty;
    public string Doctor { get; set; } = string.Empty;
    public string TimeSlot { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using sv_b681084d8a8c480c8c5735dd6f18f216.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey(nameof(Model.Email)))
            {
                <div class="validation-message">@serverErrors[nameof(Model.Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                    @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey(nameof(Model.Doctor)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.Doctor)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                    @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey(nameof(Model.TimeSlot)))
                {
                    <div class="validation-message">@serverErrors[nameof(Model.TimeSlot)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>
        </fieldset>

        <div class="mt-3 d-flex gap-2">
            <button type="button" class="btn btn-secondary" @onclick="BackToStep1">Back</button>
            <button type="button" class="btn btn-info" @onclick="CheckAvailability">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                Book Appointment
            </button>
        </div>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentFormModel Model { get; set; } = new();

    private bool showStep2;
    private bool availabilityChecked;
    private bool booked;

    private List<string> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task ProceedToStep2()
    {
        serverErrors.Clear();

        editContext = new EditContext(Model);
        var isValid = editContext.Validate();

        // Only check step-1 fields
        var step1Properties = new[]
        {
            nameof(Model.PatientName),
            nameof(Model.Email),
            nameof(Model.Phone),
            nameof(Model.InsuranceProvider)
        };

        var step1Messages = editContext.GetValidationMessages()
            .Where((_, i) => true); // all messages at this point are step-1

        // Re-validate: we only care whether step-1 fields have errors
        var hasStep1Errors = step1Properties
            .Any(p => editContext.GetValidationMessages(
                new FieldIdentifier(Model, p)).Any());

        if (hasStep1Errors)
            return;

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
        availabilityChecked = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Remove(nameof(Model.Doctor));
        serverErrors.Remove(nameof(Model.TimeSlot));
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();

        // Client-side validation first
        editContext = new EditContext(Model);
        editContext.Validate();

        var step2Properties = new[]
        {
            nameof(Model.Doctor),
            nameof(Model.AppointmentDate),
            nameof(Model.TimeSlot),
            nameof(Model.Reason)
        };

        var hasStep2Errors = step2Properties
            .Any(p => editContext.GetValidationMessages(
                new FieldIdentifier(Model, p)).Any());

        if (hasStep2Errors)
            return;

        // Server-side validation
        serverErrors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        availabilityChecked = serverErrors.Count == 0;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
        serverErrors.Clear();
    }

    private void HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        booked = true;
    }

    // ───── Form model with validation attributes ─────
    public class AppointmentFormModel
    {
        [Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Enter a valid email address.")]
        public string Email { get; set; } = string.Empty;

        [Required(ErrorMessage = "Phone number is required.")]
        [Phone(ErrorMessage = "Enter a valid phone number.")]
        public string Phone { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select an insurance provider.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a doctor.")]
        public string Doctor { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a date.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateTime? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Please select a time slot.")]
        public string TimeSlot { get; set; } = string.Empty;

        [Required(ErrorMessage = "Reason for visit is required.")]
        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string Reason { get; set; } = string.Empty;
    }

    public class FutureDateAttribute : ValidationAttribute
    {
        public override bool IsValid(object? value)
        {
            if (value is DateTime dt)
                return dt.Date > DateTime.Today;
            return false;
        }
    }
}

